DROP TABLE IF EXISTS `project_crm_panels`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `project_crm_panels` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `panel_number` int(11) NOT NULL,
  `panel_name` varchar(250) DEFAULT NULL,
  `quantity` int(11) NOT NULL DEFAULT 1,
  `markupP` decimal(5,2) DEFAULT 0.00,
  `markupM` decimal(5,2) DEFAULT 0.00,
  `manpower_pct` decimal(5,2) DEFAULT 0.00,
  `total_price` decimal(14,2) DEFAULT 0.00,
  `is_completed` tinyint(1) DEFAULT 0,
  `note` text DEFAULT NULL,
  `show_note_in_client_pdf` tinyint(1) DEFAULT 0,
  `onedrive_link` varchar(500) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_panel_project_num` (`project_id`,`panel_number`),
  KEY `updated_by` (`updated_by`),
  CONSTRAINT `project_crm_panels_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `project_crm_panels_ibfk_2` FOREIGN KEY (`updated_by`) REFERENCES `workers` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=164 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

